reduceEffect(store, state, effect) {
      if (this.superType === 3 /* ENERGY */) {
        const cardList = StateUtils.findCardList(state, this);
        if (!(cardList instanceof PokemonCardList) || !cardList.energies.cards.includes(this)) {
          this.superType = 1 /* POKEMON */;
        }
      }
      if (WAS_POWER_USED(effect, 0, this)) {
        const player = effect.player;
        if (player.energyPlayedTurn === state.turn) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        player.energyPlayedTurn = state.turn;
        let isEnergyOnBench = false;
        let isEnergyOnActive = false;
        const checkProvidedEnergy = new CheckProvidedEnergyEffect(player, player.active);
        state = store.reduceEffect(state, checkProvidedEnergy);
        const activeEnergyCount = checkProvidedEnergy.energyMap.length;
        if (activeEnergyCount > 0) {
          isEnergyOnActive = true;
        }
        const blockedTo = [];
        if (!isEnergyOnActive) {
          const target = {
            player: 2 /* BOTTOM_PLAYER */,
            slot: 1 /* ACTIVE */,
            index: 0
          };
          blockedTo.push(target);
        }
        player.bench.forEach((bench, index) => {
          if (bench.cards.length === 0) {
            return;
          }
          const checkProvidedEnergy2 = new CheckProvidedEnergyEffect(player, bench);
          state = store.reduceEffect(state, checkProvidedEnergy2);
          const energyCount = checkProvidedEnergy2.energyMap.length;
          if (energyCount > 0) {
            isEnergyOnBench = true;
          } else {
            const target = {
              player: 2 /* BOTTOM_PLAYER */,
              slot: 2 /* BENCH */,
              index
            };
            blockedTo.push(target);
          }
        });
        if (!isEnergyOnActive && !isEnergyOnBench) {
          throw new GameError(GameMessage.CANNOT_USE_POWER);
        }
        return store.prompt(
          state,
          new ChoosePokemonPrompt(
            player.id,
            GameMessage.CHOOSE_POKEMON_TO_ATTACH_CARDS,
            2 /* BOTTOM_PLAYER */,
            [1 /* ACTIVE */, 2 /* BENCH */],
            { allowCancel: false, blocked: blockedTo }
          ),
          (targets) => {
            if (!targets || targets.length === 0) {
              return;
            }
            const checkProvidedEnergy2 = new CheckProvidedEnergyEffect(player, targets[0]);
            state = store.reduceEffect(state, checkProvidedEnergy2);
            return store.prompt(
              state,
              new ChooseEnergyPrompt(
                player.id,
                GameMessage.CHOOSE_ENERGIES_TO_HAND,
                checkProvidedEnergy2.energyMap,
                [9 /* COLORLESS */],
                { allowCancel: false }
              ),
              (energy2) => {
                const cards = (energy2 || []).map((e) => e.card);
                MOVE_CARDS(store, state, targets[0], player.hand, { cards, sourceCard: this });
                effect.preventDefault = true;
                MOVE_CARDS(store, state, player.hand, targets[0], { cards: [this], sourceCard: this });
                if (!targets[0].energies.cards.includes(this)) {
                  targets[0].energies.cards.push(this);
                }
                this.superType = 3 /* ENERGY */;
              }
            );
          }
        );
      }
      if (effect instanceof CheckProvidedEnergyEffect && effect.source.energies.cards.includes(this)) {
        effect.energyMap.push({ card: this, provides: [0 /* ANY */, 0 /* ANY */] });
      }
      if (WAS_ATTACK_USED(effect, 0, this)) {
        const player = effect.player;
        let deltasInPlay = 0;
        player.forEachPokemon(2 /* BOTTOM_PLAYER */, (card) => {
          if (card.getPokemonCard()?.hasTag("Delta Species" /* DELTA_SPECIES */)) {
            deltasInPlay++;
          }
        });
        DRAW_UP_TO_X_CARDS(store, state, player, deltasInPlay);
      }
      return state;
    }

